// Меню «מחיקה» (cat-14) — диалоги закрываются «סגירה»/«ביטול», реальные товары не удаляются.
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/admin.json'),
  // fake-камера для теста «תמונה → מצלמה» (launchOptions нельзя задать внутри describe)
  permissions: ['camera'],
  launchOptions: { args: ['--use-fake-ui-for-media-stream', '--use-fake-device-for-media-stream'] },
});

const shown = (page: Page) => page.getByText(/^מציג \d+–\d+ מתוך \d+ תוצאות$/);
const minCells = (page: Page) => page.getByRole('button', { name: /^עדכון רף מינימום — / });
const rowOf = (page: Page, name: string) =>
  page.getByRole('button', { name, exact: true }).locator('xpath=ancestor::*[.//button[@aria-label="פעולות"]][1]');

async function openCatalog(page: Page) {
  await page.goto('/catalog');
  await expect(page.getByRole('heading', { level: 1, name: 'קטלוג וניהול' })).toBeVisible();
  await expect(minCells(page).first()).toBeVisible({ timeout: 20_000 });
}

async function firstRowName(page: Page) {
  const label = await minCells(page).first().getAttribute('aria-label');
  expect(label, 'aria-label у ячейки «רף מינימום»').toBeTruthy();
  return label!.replace(/^עדכון רף מינימום — /, '');
}

